#include <iostream>
#include <stdexcept>
#include <string>
#include <utility>

class Order {
public:
    Order(std::string symbol, int qty, double limitPrice)
        : symbol_{std::move(symbol)}, qty_{qty}, limitPrice_{limitPrice} {
        if (qty_ <= 0) throw std::invalid_argument("qty must be positive");
        if (limitPrice_ <= 0.0) throw std::invalid_argument("price must be positive");
    }

    const std::string& symbol() const { return symbol_; }
    int qty() const { return qty_; }
    double limitPrice() const { return limitPrice_; }
    double notional() const { return qty_ * limitPrice_; }   // computed, never stored

    void reduce(int shares) {                                // the only mutator
        if (shares <= 0 || shares > qty_) throw std::invalid_argument("bad fill");
        qty_ -= shares;
    }

private:
    std::string symbol_;
    int qty_;
    double limitPrice_;
};

int main() {
    Order o{"ESZ5", 10, 5312.25};
    std::cout << o.symbol() << " x " << o.qty() << " = " << o.notional() << '\n';
    o.reduce(4);
    std::cout << o.qty() << " remaining\n";
}

