guidedExercise.solution:
The two trades contribute $100 \times (42.75 - 42.10) = +65.00$ and $50 \times (41.20 - 41.50) = -15.00$, so the program prints `50`.

```cpp
#include <iostream>

class PnLCalculator {
public:
    void addTrade(int qty, double entryPx, double exitPx) {
        realized_ += qty * (exitPx - entryPx);
    }
    double realized() const { return realized_; }
    void reset() { realized_ = 0.0; }
private:
    double realized_ = 0.0;   // in-class default: starts clean for every ctor
};

int main() {
    PnLCalculator pnl;
    pnl.addTrade(100, 42.10, 42.75);   // +65.00
    pnl.addTrade(50, 41.50, 41.20);    // -15.00
    std::cout << pnl.realized() << '\n';   // 50
}
```

independentExercise.solution:
`5300.5 / 0.25 = 21202` exactly, so it passes; `5300.52 / 0.25 = 21202.08` is 0.08 ticks from an integer and throws.

```cpp
#include <cmath>
#include <iostream>
#include <stdexcept>
#include <string>
#include <utility>

class Instrument {
public:
    Instrument(std::string symbol, double tickSize)
        : symbol_{std::move(symbol)}, tickSize_{tickSize}, price_{0.0} {
        if (tickSize_ <= 0.0) throw std::invalid_argument("tick size must be positive");
    }
    const std::string& symbol() const { return symbol_; }
    double price() const { return price_; }
    void setPrice(double p) {
        double ticks = p / tickSize_;
        if (std::abs(ticks - std::round(ticks)) > 1e-9)
            throw std::invalid_argument("price off tick grid");
        price_ = p;
    }
private:
    std::string symbol_;
    double tickSize_;
    double price_;
};

int main() {
    Instrument i{"NQZ5", 0.25};
    i.setPrice(5300.5);          // on-tick: accepted
    // i.setPrice(5300.52);      // throws: 0.08 ticks off the grid
    std::cout << i.symbol() << " @ " << i.price() << '\n';   // NQZ5 @ 5300.5
}
```

